	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241336), '''String: "Would you like to email support\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241328), '''String: "You are our valuable sponsor.\nThe WYN team sincerely thanks you for your support.\nWhen you need support, please send an email to\n✉️: hotro@wynauto.com"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241320), '''String: "Only"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241312), '''String: "We created the WYN application to support drivers in driving safely.\nYour support helps us secure funding to maintain the project while removing ads and UNLOCKING all other features in the app.\nPlease support us with a few cups of coffee ❤️\n(Click the \"Support now\" button below)"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241304), '''String: " then pay"''', True)
