	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241248), '''String: "または、すでに支払い済みの場合は復元します"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241240), '''String: "復元に失敗しました"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241232), '''String: "顧客コードがメモリにコピーされました"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241224), '''String: "お客様のコード"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241216), '''String: "サポートに電子メールを送信しますか\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241208), '''String: "あなたは私たちの貴重なスポンサーです。\nWYNチーム一同、皆様のご支援に心より感謝申し上げます。\nサポートが必要な場合は、次の宛先にメールを送信してください\n✉️: hotro@wynauto.com"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241200), '''String: "のみ"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241192), '''String: "ドライバーの安全運転をサポートするアプリ「WYN」を開発しました。\nあなたのサポートは、広告を削除し、アプリ内の他のすべての機能をロック解除しながら、プロジェクトを維持するための資金を確保するのに役立ちます。\nコーヒーでも飲みながら応援してください❤️\n（下の「今すぐサポート」ボタンをクリックしてください）"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241184), '''String: "試してから支払う"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241176), '''String: "일"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241168), '''String: "개월"''', True)
