	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241144), '''String: "지금 지원하세요"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241136), '''String: "복원하다"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241128), '''String: "또는 이미 지불한 경우 복원"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241120), '''String: "복원 실패"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241112), '''String: "고객 코드가 메모리에 복사되었습니다."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241104), '''String: "고객의 코드"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241096), '''String: "지원팀에 이메일을 보내시겠습니까\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241088), '''String: "당신은 우리의 소중한 후원자입니다.\nWYN 팀은 귀하의 지원에 진심으로 감사드립니다.\n지원이 필요하시면 이메일을 보내주세요.\n✉️: hotro@wynauto.com"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241080), '''String: "오직"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241072), '''String: "운전자의 안전한 운전을 지원하기 위해 WYN 애플리케이션을 만들었습니다.\n귀하의 지원은 광고를 제거하고 앱의 다른 모든 기능을 잠금 해제하는 동시에 프로젝트를 유지하기 위한 자금을 확보하는 데 도움이 됩니다.\n커피 몇잔으로 응원해주세요❤️\n(아래 \'지금 지원하기\' 버튼을 클릭하세요)"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241064), '''String: "일 동안 사용해보고 결제하세요"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241056), '''String: " ngày"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241048), '''String: " tháng"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241040), '''String: " tuần"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241032), '''String: " năm"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241024), '''String: "Ủng hộ ngay"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241016), '''String: "Khôi phục"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241008), '''String: "Hoặc khôi phục lại nếu bạn đã thanh toán"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 241000), '''String: "Khôi phục không thành công"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240992), '''String: "Đã copy mã khách hàng vào bộ nhớ"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240984), '''String: "Mã khách hàng"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240976), '''String: "Bạn có muốn gửi email yêu cầu hỗ trợ\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240968), '''String: "Bạn đang là nhà tài trợ quý giá của chúng tôi.\nĐội ngũ WYN xin chân thành cảm ơn sự ủng hộ của bạn.\nKhi cần hỗ trợ, bạn vui lòng gửi email đến \n✉️: hotro@wynauto.com"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240960), '''String: "Chỉ"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 240952), '''String: "Ứng dụng WYN được chúng tôi tạo ra để hỗ trợ các bác tài lái xe an toàn.\nSự ủng hộ của bạn giúp chúng tôi đảm bảo kinh phí để duy trì dự án đồng thời xóa bỏ quảng cáo và MỞ KHÓA toàn bộ tính năng khác trong ứng dụng.\nỦng hộ chúng tôi ít ly cafe bạn nhé ❤️ \n(Nhấn nút \"Ủng hộ ngay\" bên dưới)"''', True)
