	ida_struct.set_member_cmt(ida_struct.get_member(struc, 204768), '''String: "차량이 움직이는 방향으로 장치를 고정하세요.\n차량이 평탄한 도로에 정차한 상태에서 버튼을 누르면"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 204760), '''String: "알겠습니다. 안내를 다시 표시하지 마세요."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 204752), '''String: "위도: N/A, 경도: N/A"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 204744), '''String: "동의 및 계속"''', True)
