	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136840), '''String: "{{appName}}有新的版本！您拥有{{currentInstalledVersion}}的版本可更新到{{currentAppStoreVersion}}的版本。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136832), '''String: "Đã có phiên bản mới của {{appName}}. Phiên bản {{currentAppStoreVersion}} đã sẵn sàng, bạn đang dùng {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136824), '''String: "Доступна нова версія додатка {{appName}}! Нова версія: {{currentAppStoreVersion}}, поточна версія: {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136816), '''String: "{{appName}} uygulamanızın yeni bir versiyonu mevcut! Versiyon {{currentAppStoreVersion}} şu anda erişilebilir, mevcut sürümünüz {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136808), '''String: "{{appName}} యాప్ యొక్క కొత్త వెర్షన్ అందుబాటులో ఉంది. వెర్షన్ {{currentAppStoreVersion}} అందుబాటులో ఉంది కానీ మీ దగ్గర {{currentInstalledVersion}} ఉంది."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136800), '''String: "{{appName}}-ன் புதிய பதிப்பு {{currentAppStoreVersion}} இப்போது கிடைக்கிறது! உங்களிடம் {{currentInstalledVersion}} உள்ளது."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136792), '''String: "En ny version av {{appName}} är tillgänglig! Version {{currentAppStoreVersion}} är tillgänglig - du har {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136784), '''String: "Доступна новая версия приложения {{appName}}! Новая версия: {{currentAppStoreVersion}}, текущая версия: {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136776), '''String: "د {{appName}} آپلیکشن  نوې نسخه شتون لري! {{currentAppStoreVersion}} شتون لري، مګر تاسو اوس هم {{currentInstalledVersion}} کاروئ."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136768), '''String: "Nowa wersja {{appName}} jest dostępna! Wersja {{currentAppStoreVersion}} jest dostępna, Ty masz {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136760), '''String: "Há uma nova versão do {{appName}} disponível! A versão {{currentAppStoreVersion}} já está disponível, você tem a {{currentInstalledVersion}}."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 136752), '''String: "Er is een nieuwe versie van {{appName}} beschikbaar! De nieuwe versie is {{currentAppStoreVersion}}, je gebruikt nu versie {{currentInstalledVersion}}."''', True)
